// Controle de acesso: o pedido pertence ao usuário autenticado?
@GetMapping("/pedidos/{id}")
PedidoResponse buscar(@PathVariable Long id, @AuthenticationPrincipal Jwt jwt) {
    Pedido pedido = service.buscar(id);
    if (!pedido.clienteId().equals(jwt.getSubject())) {
        throw new AccessDeniedException("Pedido de outro cliente");
    }
    return PedidoResponse.from(pedido);
}

